setvar VAR_TEMP_1 3
end
= RusturfTunnel_EventScript_TunnelBlockagePos2
setvar VAR_TEMP_1 2
end
= RusturfTunnel_EventScript_AquaGruntBackUp
lockall
msgbox	What, are you coming? Come and get some, then!
closemessage
applymovement LOCALID_RUSTURF_TUNNEL_GRUNT RusturfTunnel_Movement_GruntAndPeekoBackUp
applymovement LOCALID_RUSTURF_TUNNEL_PEEKO RusturfTunnel_Movement_GruntAndPeekoBackUp
waitmovement 0
copyobjectxytoperm LOCALID_RUSTURF_TUNNEL_GRUNT
copyobjectxytoperm LOCALID_RUSTURF_TUNNEL_PEEKO
setvar VAR_RUSTURF_TUNNEL_STATE 3
releaseall
end
= RusturfTunnel_EventScript_TunnelBlockagePos1
setvar VAR_TEMP_1 1
end
= RusturfTunnel_EventScript_Wanda
lock
faceplayer
msgbox	On the other side of this rock… My boyfriend is there.He… He's not just digging the tunnel to come see me.He works his hands raw and rough for the benefit of everyone.
closemessage
applymovement VAR_LAST_TALKED Common_Movement_FaceOriginalDirection
waitmovement 0
release
end
= RusturfTunnel_EventScript_Mike
trainerbattle_single TRAINER_MIKE_2 RusturfTunnel_Text_MikeIntro RusturfTunnel_Text_MikeDefeat
msgbox	They halted development here to protect POKéMON, right? There's a feel-good story!
end
= EventScript_RockSmash
lockall
goto_if_unset FLAG_BADGE03_GET EventScript_CantSmashRock
checkpartymove MOVE_ROCK_SMASH
goto_if_eq VAR_RESULT PARTY_SIZE EventScript_CantSmashRock
setfieldeffectargument 0 VAR_RESULT
bufferpartymonnick STR_VAR_1 VAR_RESULT
buffermovename STR_VAR_2 MOVE_ROCK_SMASH
msgboxyesno	Dieser Felsen sieht zerbrechlich aus. Möchtest du ZERTRÜMMERER einsetzen?
goto_if_eq VAR_RESULT NO EventScript_CancelSmash
msgbox	STR_VAR_1 setzt STR_VAR_2 ein!
closemessage
dofieldeffect FLDEFF_USE_ROCK_SMASH
waitstate
goto EventScript_SmashRock
end
@ Use rock smash from party menu
goto EventScript_UseRockSmash
= EventScript_UseRockSmash
lockall
dofieldeffect FLDEFF_USE_ROCK_SMASH
waitstate
goto EventScript_SmashRock
end
= EventScript_SmashRock
applymovement VAR_LAST_TALKED Movement_SmashRock
waitmovement 0
removeobject VAR_LAST_TALKED
specialvar VAR_RESULT TryUpdateRusturfTunnelState
goto_if_eq VAR_RESULT TRUE EventScript_EndSmash
special RockSmashWildEncounter
goto_if_eq VAR_RESULT FALSE EventScript_EndSmash
waitstate
releaseall
end
= EventScript_EndSmash
releaseall
end
= EventScript_CancelSmash
closemessage
releaseall
end
= EventScript_CantSmashRock
msgbox	Das ist ein robuster Felsen, aber vielleicht kann ihn ein POKéMON zertrümmern.
releaseall
end
= RusturfTunnel_EventScript_Peeko
lock
faceplayer
waitse
playmoncry SPECIES_WINGULL CRY_MODE_NORMAL
msgbox	PEEKO: Pii pihyoh!
waitmoncry
release
end
= RusturfTunnel_EventScript_Grunt
lock
faceplayer
playbgm MUS_ENCOUNTER_AQUA FALSE
msgbox	Grah, keelhaul it all!That hostage POKéMON turned out to be worthless!And to think I made a getaway… In this tunnel to nowhere!Hey! You! So you want to battle me?
trainerbattle_no_intro TRAINER_GRUNT_RUSTURF_TUNNEL RusturfTunnel_Text_GruntDefeat
msgbox	This is plain not right…The BOSS told me this would be a slick-and-easy job to pull.All I had to do was steal some package from DEVON.Tch! You want it back that badly, take it!
giveitem ITEM_DEVON_GOODS
closemessage
applymovement LOCALID_PLAYER RusturfTunnel_Movement_PushPlayerAsideForGrunt
applymovement LOCALID_RUSTURF_TUNNEL_GRUNT RusturfTunnel_Movement_GruntEscape
waitmovement 0
removeobject LOCALID_RUSTURF_TUNNEL_GRUNT
delay 50
addobject LOCALID_RUSTURF_TUNNEL_BRINEY
applymovement LOCALID_RUSTURF_TUNNEL_BRINEY RusturfTunnel_Movement_BrineyApproachPeeko1
waitmovement 0
applymovement LOCALID_PLAYER RusturfTunnel_Movement_PlayerMoveAsideForBriney
